#!/data/data/com.termux/files/usr/bin/bash
set -e

echo "=== Исправления: логотип, обрезка кнопки отчёта, переименование в FinArs, экран 'О приложении' ==="

mkdir -p app/src/main/res/drawable

echo "--- Записываю логотип в res/drawable/logo.png ---"
base64 -d << 'B64EOF' > app/src/main/res/drawable/logo.png

B64EOF
echo "OK: logo.png записан"

# -----------------------------------------------------------------
# 1) activity_mine.xml:
#    - убираем baseline-выравнивание в ряду кнопок Settings/Report,
#      из-за которого 2-строчный текст обрезался снизу
#    - заменяем текстовый лого "FA" на картинку логотипа
# -----------------------------------------------------------------
python3 - << 'PYEOF'
import re
path = "app/src/main/res/layout/activity_mine.xml"
with open(path, encoding="utf-8") as f:
    content = f.read()

pattern_row = re.compile(r'(<LinearLayout(?:(?!>).)*?weightSum="2"(?:(?!>).)*?)>', re.DOTALL)
new_content, n1 = pattern_row.subn(r'\1 android:baselineAligned="false">', content, count=1)
if n1 != 1:
    raise SystemExit("ERROR: не найден ряд кнопок (weightSum=2) в activity_mine.xml")
content = new_content
print("OK: baselineAligned=false добавлен на ряд кнопок")

pattern_logo = re.compile(r'<TextView(?:(?!/>).)*?android:text="FA"(?:(?!/>).)*?/>', re.DOTALL)
new_image = (
    '<ImageView\n'
    '            android:id="@+id/iv_logo"\n'
    '            android:layout_width="120dp"\n'
    '            android:layout_height="120dp"\n'
    '            android:layout_gravity="center_horizontal"\n'
    '            android:layout_marginBottom="4dp"\n'
    '            android:adjustViewBounds="true"\n'
    '            android:src="@drawable/logo"\n'
    '            android:contentDescription="@string/app_name"/>'
)
new_content, n2 = pattern_logo.subn(new_image, content, count=1)
if n2 != 1:
    raise SystemExit('ERROR: не найден TextView с text="FA" в activity_mine.xml')
content = new_content
print("OK: текстовый лого FA заменён на ImageView с картинкой")

with open(path, "w", encoding="utf-8") as f:
    f.write(content)
PYEOF

# -----------------------------------------------------------------
# 2) strings.xml: переименование в FinArs + строки для "О приложении"
# -----------------------------------------------------------------
python3 - << 'PYEOF'
path = "app/src/main/res/values/strings.xml"
with open(path, encoding="utf-8") as f:
    content = f.read()

old_name = '<string name="app_name">F.A księgowy</string>'
new_name = '<string name="app_name">FinArs</string>'
if old_name not in content:
    raise SystemExit(f"ERROR: не найдена строка app_name в {path}")
content = content.replace(old_name, new_name)
print("OK: app_name -> FinArs")

about_description = (
    "FinArs — удобное приложение для ведения финансов нерегистрируемой деятельности. "
    "Легко учитывайте доходы и расходы, контролируйте текущий баланс, автоматически "
    "рассчитывайте налоги и формируйте отчёты. Приложение помогает соблюдать лимиты, "
    "отслеживать финансовые показатели и всегда иметь под рукой полную историю операций. "
    "Простой интерфейс и быстрый ввод данных делают ежедневный учёт максимально удобным.\\n\\n"
    "Основные возможности:\\n"
    "💰 Учёт доходов и расходов.\\n"
    "📊 Автоматический расчёт прибыли.\\n"
    "🧾 Расчёт налогов.\\n"
    "📈 Контроль лимитов нерегистрируемой деятельности.\\n"
    "📄 Генерация отчётов.\\n"
    "🔍 История всех операций.\\n"
    "🌙 Современный тёмный интерфейс.\\n"
    "🔒 Все данные хранятся локально на устройстве.\\n\\n"
    "Связь: p.arsenii@interia.pl"
)

about_strings = (
    '    <string name="about_app">О приложении</string>\n'
    f'    <string name="about_description">{about_description}</string>\n'
    '    <string name="about_email">p.arsenii@interia.pl</string>\n'
)

marker = "</resources>"
if marker not in content:
    raise SystemExit(f"ERROR: не найден закрывающий тег resources в {path}")
content = content.replace(marker, about_strings + marker)
print("OK: добавлены строки about_app / about_description / about_email")

with open(path, "w", encoding="utf-8") as f:
    f.write(content)
PYEOF

# -----------------------------------------------------------------
# 3) activity_settings.xml: добавляем кнопку "О приложении"
# -----------------------------------------------------------------
python3 - << 'PYEOF'
path = "app/src/main/res/layout/activity_settings.xml"
with open(path, encoding="utf-8") as f:
    content = f.read()

about_button = '''
    <View android:layout_width="match_parent" android:layout_height="1dp"
        android:background="#2A2E60" android:layout_marginTop="20dp" android:layout_marginBottom="20dp"/>

    <Button android:id="@+id/btn_about" android:layout_width="match_parent" android:layout_height="52dp"
        android:text="@string/about_app" android:textAllCaps="false" android:textColor="@color/text_primary"
        android:background="@drawable/btn_pill_outline"/>
'''

idx = content.rfind("</LinearLayout>")
if idx == -1:
    raise SystemExit(f"ERROR: не найден закрывающий </LinearLayout> в {path}")
content = content[:idx] + about_button + "\n" + content[idx:]

with open(path, "w", encoding="utf-8") as f:
    f.write(content)
print("OK: кнопка 'О приложении' добавлена в activity_settings.xml")
PYEOF

# -----------------------------------------------------------------
# 4) SettingsActivity.kt: обработчик кнопки "О приложении"
# -----------------------------------------------------------------
python3 - << 'PYEOF'
import re
path = "app/src/main/java/com/example/fa_ksiegowy/SettingsActivity.kt"
with open(path, encoding="utf-8") as f:
    content = f.read()

if "import android.app.AlertDialog" not in content:
    content = content.replace(
        "import android.content.Intent",
        "import android.app.AlertDialog\nimport android.content.Intent\nimport android.net.Uri",
        1
    )
    print("OK: добавлены импорты AlertDialog / Uri")

pattern = re.compile(
    r'([ \t]*)findViewById<Button>\(R\.id\.btn_lang_en\)\.setOnClickListener \{ setLocale\("en"\) \}\n'
)
m = pattern.search(content)
if not m:
    raise SystemExit("ERROR: не найден обработчик btn_lang_en в SettingsActivity.kt")
indent = m.group(1)

about_block = (
    f'{indent}findViewById<Button>(R.id.btn_about).setOnClickListener {{\n'
    f'{indent}    AlertDialog.Builder(this)\n'
    f'{indent}        .setTitle(getString(R.string.about_app))\n'
    f'{indent}        .setMessage(getString(R.string.about_description))\n'
    f'{indent}        .setPositiveButton("Написать") {{ _, _ ->\n'
    f'{indent}            val intent = Intent(Intent.ACTION_SENDTO).apply {{\n'
    f'{indent}                data = Uri.parse("mailto:" + getString(R.string.about_email))\n'
    f'{indent}            }}\n'
    f'{indent}            startActivity(intent)\n'
    f'{indent}        }}\n'
    f'{indent}        .setNegativeButton("Закрыть", null)\n'
    f'{indent}        .show()\n'
    f'{indent}}}\n'
)

content = content[:m.end()] + about_block + content[m.end():]

with open(path, "w", encoding="utf-8") as f:
    f.write(content)
print("OK: добавлен обработчик кнопки 'О приложении' в SettingsActivity.kt")
PYEOF

echo "--- Готово, коммичу и пушу ---"

git add .
git commit -m "Rename app to FinArs, add logo image, fix report button clipping, add About screen"
git push
